/**
 * 分流对话 Tab 组件。
 *
 * 流程：
 *  1. 读取当前会话工作区 cwd（api.sessionCwd）
 *  2. 扫描项目文件（api.fsTree 递归 + 排除规则过滤）
 *  3. 用户勾选要打包的文件（或全选），设定 token 预算
 *  4. 读取文件内容（api.fsRead），组装 prompt
 *  5. 一键复制剪贴板（navigator.clipboard）
 *  6. 半自动分流引导：提示用户手动粘贴到 DeepSeek 网页版免费对话
 *
 * 合规边界：只读本地文件 + 复制剪贴板，不操控浏览器、不调网页接口。
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { api, scopeOf } from './api'
import type { TabComponentProps } from 'dsh-better-sidebar'
import {
  DEFAULT_EXCLUDES, shouldInclude, assemblePrompt, buildTreeText, extLang,
} from './pack'

type Phase = 'loading' | 'scanning' | 'select' | 'preview' | 'copied'

const MAX_FILES = 300
const MAX_BYTES = 3 * 1024 * 1024 // 单文件 3MB 上限

export function DualBridgeTab(props: TabComponentProps): React.ReactNode {
  const { scope } = props

  const [cwd, setCwd] = useState<string>('')
  const [root, setRoot] = useState<string>('')
  const [allFiles, setAllFiles] = useState<{ relPath: string; path: string; size: number }[]>([])
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [tokenBudget, setTokenBudget] = useState(8000)
  const [phase, setPhase] = useState<Phase>('loading')
  const [error, setError] = useState<string>('')
  const [result, setResult] = useState<{ prompt: string; tokens: number; fileCount: number } | null>(null)
  const [search, setSearch] = useState('')

  // 组件卸载时取消未完成的异步操作
  const disposedRef = useRef(false)
  useEffect(() => () => {
    disposedRef.current = true
  }, [])

  // 1. 加载工作区
  useEffect(() => {
    let cancelled = false
    ;(async () => {
      try {
        const info = await api.sessionCwd(scope)
        if (cancelled) return
        setCwd(info.cwd)
        setRoot(info.root)
        setPhase('scanning')
      } catch (e) {
        if (!cancelled) setError(`读取工作区失败：${(e as Error).message}`)
      }
    })()
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scope.sessionId])

  // 2. 扫描项目文件
  const scan = useCallback(async () => {
    if (!cwd && !root) {
      setError('工作区尚未就绪，请稍后再试')
      return
    }
    setPhase('scanning')
    setError('')
    try {
      const rootPath = cwd || root
      const found: { relPath: string; path: string; size: number }[] = []
      // BFS 逐层遍历，避免深目录卡死
      const queue: string[] = [rootPath]
      const visited = new Set<string>()
      const excludeArr = [...DEFAULT_EXCLUDES]

      while (queue.length > 0) {
        // 先进先出，保持目录层级顺序稳定
        const dir = queue.shift()!
        if (visited.has(dir)) continue
        visited.add(dir)

        let tree
        try {
          tree = await api.fsTree(scope, dir, excludeArr)
        } catch {
          continue // 单个目录读不了就跳过
        }
        for (const entry of tree.entries) {
          const relPath = entry.path.startsWith(rootPath + '/')
            ? entry.path.slice(rootPath.length + 1)
            : entry.path
          if (entry.isDir) {
            if (shouldInclude(relPath + '/', excludeArr)) queue.push(entry.path)
          } else {
            if (shouldInclude(relPath, excludeArr)) found.push({ relPath, path: entry.path, size: 0 })
          }
        }
        if (found.length >= MAX_FILES) break
      }
      // 扫描完成后，附带获取文件大小（batch 获取，失败不阻塞）
      try {
        await Promise.all(found.slice(0, 50).map(async (f) => {
          const read = await api.fsRead(scope, f.path)
          if (read.kind === 'text' || read.kind === 'binary' || read.kind === 'too-large') f.size = read.size
        }))
      } catch {
        // 大小获取失败不阻塞扫描
      }

      if (disposedRef.current) return
      // 按路径排序，稳定展示
      found.sort((a, b) => a.relPath.localeCompare(b.relPath))
      setAllFiles(found)
      setSelected(new Set(found.map((f) => f.relPath)))
      setPhase('select')
    } catch (e) {
      if (disposedRef.current) return
      setError(`扫描失败：${(e as Error).message}`)
      setPhase('select')
    }
  }, [cwd, root, scope])

  // 3. 组装 prompt 并复制
  const packAndCopy = useCallback(async () => {
    setPhase('preview')
    setError('')
    try {
      const picked = allFiles.filter((f) => selected.has(f.relPath))
      const contents: { relPath: string; content: string }[] = []
      let totalBytes = 0
      let skippedLarge = 0
      let skippedBin = 0

      for (const f of picked) {
        if (contents.length >= MAX_FILES) break
        const read = await api.fsRead(scope, f.path)
        if (read.kind === 'text') {
          if (read.size > MAX_BYTES) {
            skippedLarge++
            continue
          }
          contents.push({ relPath: f.relPath, content: read.content })
          totalBytes += read.size
        } else if (read.kind === 'binary' || read.kind === 'too-large') {
          skippedBin++
        }
      }

      const treeText = buildTreeText(contents)
      const pack = assemblePrompt(treeText, contents)
      const skippedNote =
        skippedLarge > 0 || skippedBin > 0
          ? `（已跳过 ${skippedLarge} 个超大文件、${skippedBin} 个二进制文件）`
          : ''
      setResult({ ...pack, fileCount: contents.length })
      setPhase('preview')
      setError(
        pack.tokens > tokenBudget
          ? `⚠️ 打包后约 ${pack.tokens.toLocaleString()} token，超过预算 ${tokenBudget.toLocaleString()}。请减少文件或调大预算。${skippedNote}`
          : skippedNote || '',
      )
    } catch (e) {
      setError(`打包失败：${(e as Error).message}`)
      setPhase('select')
    }
  }, [allFiles, selected, scope, tokenBudget])

  // 复制（与打包分开，便于超限时用户调整后重试）
  const doCopy = useCallback(async () => {
    if (!result) return
    try {
      await navigator.clipboard.writeText(result.prompt)
      setPhase('copied')
      setError('')
    } catch (e) {
      setError(`复制失败：${(e as Error).message}，可手动选中文本复制`)
    }
  }, [result])

  const toggleFile = (relPath: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(relPath)) next.delete(relPath)
      else next.add(relPath)
      return next
    })
  }

  const selectAll = () => setSelected(new Set(allFiles.map((f) => f.relPath)))
  const clearAll = () => setSelected(new Set())
  const selectTextOnly = () =>
    setSelected(new Set(allFiles.filter((f) => extLang(f.relPath) !== 'text').map((f) => f.relPath)))

  // 过滤后的文件列表（支持搜索）
  const filteredFiles = useMemo(() => {
    if (!search.trim()) return allFiles
    const q = search.toLowerCase()
    return allFiles.filter((f) => f.relPath.toLowerCase().includes(q))
  }, [allFiles, search])

  // 统计已选文件的估算 token（基于路径长度近似，仅展示）
  const selectedCount = selected.size

  // ---- 渲染 ----
  return (
    <div style={styles.root}>
      <div style={styles.headerRow}>
        <div style={styles.header}>⇄ 分流对话</div>
        <span style={styles.badge}>半自动 · 合规</span>
      </div>
      <div style={styles.subheader}>
        复杂推理 → Harness API（计费）｜项目阅读 → 网页版免费
      </div>

      {error && <div style={styles.error}>{error}</div>}

      {/* 工作区信息 */}
      <div style={styles.infoBox}>
        <div><b>工作区：</b>{cwd || '读取中…'}</div>
      </div>

      {phase === 'loading' && (
        <div style={styles.status}>⏳ 正在加载工作区…</div>
      )}
      {phase === 'scanning' && (
        <div style={styles.status}>🔍 正在扫描项目文件（BFS 遍历中）…</div>
      )}

      {phase !== 'loading' && phase !== 'scanning' && (
        <div style={styles.controls}>
          <div style={styles.row}>
            <button style={styles.btn} onClick={scan}>↻ 重新扫描</button>
            <button style={styles.btn} onClick={selectAll} disabled={allFiles.length === 0}>全选</button>
            <button style={styles.btn} onClick={selectTextOnly} disabled={allFiles.length === 0}>仅代码</button>
            <button style={styles.btn} onClick={clearAll} disabled={allFiles.length === 0}>清空</button>
          </div>
          <div style={styles.row}>
            <label style={styles.label}>token 预算：
              <input
                type="number"
                value={tokenBudget}
                min={1000}
                max={100000}
                step={1000}
                onChange={(e) => setTokenBudget(Number(e.target.value) || 8000)}
                style={styles.input}
              />
            </label>
            <span style={styles.count}>已选 {selectedCount} / {allFiles.length} 个</span>
          </div>
          {allFiles.length > 0 && (
            <input
              type="text"
              placeholder="🔎 搜索文件…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={styles.search}
            />
          )}
        </div>
      )}

      {/* 文件列表 */}
      {phase === 'select' && (
        <div style={styles.fileList}>
          {allFiles.length === 0 && (
            <div style={styles.status}>未找到可打包的文件（已按排除规则过滤）</div>
          )}
          {filteredFiles.map((f) => (
            <label key={f.relPath} style={styles.fileRow}>
              <input
                type="checkbox"
                checked={selected.has(f.relPath)}
                onChange={() => toggleFile(f.relPath)}
              />
              <span style={styles.fileName}>{f.relPath}</span>
              {f.size > 0 && (
                <span style={styles.fileSize}>{formatSize(f.size)}</span>
              )}
              <span style={styles.fileLang}>{extLang(f.relPath)}</span>
            </label>
          ))}
          {search && filteredFiles.length === 0 && (
            <div style={styles.status}>没有匹配 "{search}" 的文件</div>
          )}
        </div>
      )}

      {/* 预览 / 已复制 */}
      {phase === 'preview' && result && (
        <div style={styles.previewBox}>
          <div style={styles.previewTitle}>
            打包预览：{result.fileCount} 个文件 · 约 <b>{result.tokens.toLocaleString()}</b> token
            {error && <span style={styles.warn}>（超预算）</span>}
          </div>
          <pre style={styles.previewText}>
            {result.prompt.slice(0, 600)}{result.prompt.length > 600 ? '\n…（已截断预览）' : ''}
          </pre>
          <div style={styles.row}>
            <button style={styles.btnPrimary} onClick={doCopy}>📋 复制到剪贴板</button>
            <button style={styles.btn} onClick={() => setPhase('select')}>← 返回调整</button>
          </div>
        </div>
      )}

      {phase === 'copied' && result && (
        <div style={styles.copiedBox}>
          <div style={styles.copiedTitle}>✅ 已复制到剪贴板（{result.tokens.toLocaleString()} token，{result.fileCount} 个文件）</div>
          <ol style={styles.steps}>
            <li>切到 <b>DeepSeek 网页版</b>，新建一个对话</li>
            <li>在输入框 <b>Cmd/Ctrl + V</b> 粘贴</li>
            <li>输入你的问题，使用<b>免费</b>对话完成项目阅读/答疑</li>
            <li>如需复杂推理 / 改代码，回到 Harness 走 API（计费）</li>
          </ol>
          <div style={styles.row}>
            <button style={styles.btn} onClick={() => setPhase('select')}>← 返回选择</button>
            <button style={styles.btn} onClick={doCopy}>↻ 重新复制</button>
          </div>
        </div>
      )}
    </div>
  )
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes}B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`
}

